def _drf_get_events(
    params: dict[str, str],
    headers: dict[str, str] | None = None,
) -> tuple[int, Any]:
    client = APIClient()
    # Typed as dict[str, Any] so the **-unpacking stays compatible with the
    # stubbed APIClient.get(..., follow: bool, **extra) signature.
    extra: dict[str, Any] = {
        f"HTTP_{name.upper().replace('-', '_')}": value
        for name, value in (headers or {}).items()
    }
    response = client.get("/api/events/", params, **extra)
    return response.status_code, response.json()


def _bolt_get_events(
    module: ModuleType,
    params: dict[str, str],
    headers: dict[str, str] | None = None,
) -> tuple[int, Any]:
    with TestClient(module.api) as client:
        response = client.get("/api/events/", params=params, headers=headers)
    return response.status_code, response.json()


