from collections.abc import Mapping

_DEFAULT_DATABASE_SETTINGS = {
    "NAME": "family_scheduler",
    "USER": "postgres",
    "PASSWORD": "mysecretpassword",  # pragma: allowlist secret
    "HOST": "localhost",
    "PORT": "5432",
}

_TEST_DATABASE_SETTINGS = {
    "NAME": "family_scheduler",
    "USER": "family_scheduler",
    "PASSWORD": "dev_password_123",  # pragma: allowlist secret
    "HOST": "localhost",
    "PORT": "5432",
}


def detect_running_tests(
    *, argv0: str, env: Mapping[str, str], loaded_module_names: set[str]
) -> bool:
    return (
        "pytest" in argv0
        or bool(env.get("PYTEST_CURRENT_TEST"))
        or "pytest" in loaded_module_names
    )


def resolve_database_connection_settings(
    env: Mapping[str, str], *, running_tests: bool
) -> dict[str, str]:
    defaults = _TEST_DATABASE_SETTINGS if running_tests else _DEFAULT_DATABASE_SETTINGS

    return {
        "NAME": env.get("DB_NAME", defaults["NAME"]),
        "USER": env.get("DB_USER", defaults["USER"]),
        "PASSWORD": env.get("DB_PASSWORD", defaults["PASSWORD"]),
        "HOST": env.get("DB_HOST", defaults["HOST"]),
        "PORT": env.get("DB_PORT") or env.get("POSTGRES_PORT") or defaults["PORT"],
    }


def resolve_default_database_conn_max_age(
    env: Mapping[str, str], *, running_tests: bool, debug: bool
) -> int:
    explicit_override = env.get("CONN_MAX_AGE")
    if explicit_override is not None:
        return int(explicit_override)

    if running_tests or debug:
        return 0

    if env.get("FAMILY_SCHEDULER_RUNNING_ASGI", "").lower() in {"1", "true", "yes"}:
        return 0

    if "ASGI_THREADS" in env:
        return 0

    return 60


def resolve_celery_connection_settings(
    env: Mapping[str, str], *, running_tests: bool
) -> dict[str, str]:
    if running_tests:
        return {
            "BROKER_URL": env.get("CELERY_BROKER_URL", "memory://"),
            "RESULT_BACKEND": env.get("CELERY_RESULT_BACKEND", "cache+memory://"),
        }

    return {
        "BROKER_URL": env.get("CELERY_BROKER_URL", "redis://redis:6379/0"),
        "RESULT_BACKEND": env.get("CELERY_RESULT_BACKEND", "redis://redis:6379/0"),
    }

