    from users.models import (
        DEFAULT_FAMILY_HELPER_AGENT_NAME,
        FamilyGroup,
        FamilyGroupType,
        FamilyMembership,
    )
except Exception:
    return defaults

# This processor runs on every authenticated page render, so resolve the
# user's family data with a fixed number of queries: one membership fetch
# (with family + feature settings joined) and one bulk group-type fetch.
# This replaces separate calls to _get_user_primary_family_settings,
# get_user_immediate_family, an is_admin EXISTS query, and a navbar
# primary-family fallback, which each re-queried memberships.
profile = getattr(request.user, "profile", None)
primary_family = getattr(profile, "primary_family", None) if profile else None

memberships = list(
    FamilyMembership.objects.filter(
        user=request.user, is_active=True
    ).select_related("family", "family__feature_settings")
)

family_type_ids = {membership.family_id for membership in memberships}
if primary_family is not None:
    family_type_ids.add(primary_family.id)
family_types: dict[Any, str] = (
    dict(
        FamilyGroupType.objects.filter(family_id__in=family_type_ids).values_list(
            "family_id", "type"
        )
    )
    if family_type_ids
    else {}
)

def _feature_settings_for(membership: Any) -> Any:
    try:
        return membership.family.feature_settings
    except FamilyFeatureSettings.DoesNotExist:
        return None

# Mirrors users.feature_gate._get_user_primary_family_settings: prefer the
# primary family's settings, falling back to the first active membership.
settings_obj = None
if profile is not None and profile.primary_family_id:
    primary_membership = next(
        (
            membership
            for membership in memberships
            if membership.family_id == profile.primary_family_id
        ),
        None,
    )
    if primary_membership is not None:
        settings_obj = _feature_settings_for(primary_membership)
    else:
        try:
            settings_obj = FamilyFeatureSettings.objects.select_related(
                "family"
            ).get(family_id=profile.primary_family_id)
        except FamilyFeatureSettings.DoesNotExist:
            settings_obj = None
if settings_obj is None and memberships:
    settings_obj = _feature_settings_for(memberships[0])
if not settings_obj:
    return defaults

features = {
    "trips_enabled": settings_obj.trips_enabled,
    "organize_enabled": settings_obj.organize_enabled,
    "households_enabled": settings_obj.households_enabled,
    "groceries_enabled": settings_obj.groceries_enabled,
    "recipes_enabled": settings_obj.recipes_enabled,
    "meals_enabled": settings_obj.meals_enabled,
    "agent_enabled": settings_obj.agent_enabled,
    "clancy_available": False,
    "helper_agent_name": (
        (settings_obj.family.helper_agent_name or "").strip()
        or DEFAULT_FAMILY_HELPER_AGENT_NAME
    ),
